package com.tfluid.xdrive.core

import java.util.Base64
import org.junit.Assert.*
import org.junit.Test

/**
 * Fixed cross-runtime encrypted fixture generated by WebCrypto, not by the
 * Kotlin decryptor. Private material is test-only and must never be reused.
 */
class XDriveClipboardTargetCryptoTest {
    private val fixture = XDriveClipboardTargetCrypto.Wire(
        clientEventID = "12d922e2-7cca-4315-9c98-bd83e679cb90",
        targetDeviceID = "a8d11b3e-eaf7-4a8a-aedb-3c51908c6df2",
        kind = "application/x-xdrive-node-ref",
        nonce = "+fyvZcCVJT9O9uyL",
        ciphertext = "e3g43zd96HkSPwOLQrU8NtUrN6dIJkXQ6Q==",
        ephemeralKey = "LVkKQcvSXWnWgbHgLWCEPLGTWrd8cJNBEncrkUketwY=",
        wrappedKey = "1y/y0nl6NKA1L6J8lLxTZMZHEtmjjZ0y6SYIwTDZl27EHatdWkCZJNTDUt8J4GiJVT+Fc0Oqi940uisS",
        nodeID = 118L,
    )
    private val key = Base64.getDecoder().decode(
        "MC4CAQAwBQYDK2VuBCIEIDlLocMMuTDyDVsTd7i6Xb2aZQWnK5SNojI/DcjTIHDf"
    )
    private val scope = "https://nas.example:12"

    @Test fun decryptWebCryptoFileReferenceAndRefuseTampering() {
        assertEquals("asset:118", XDriveClipboardTargetCrypto.decrypt(
            scope, fixture.targetDeviceID, key, fixture))
        for (wire in listOf(
            fixture.copy(nodeID = 119L),
            fixture.copy(targetDeviceID = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"),
            fixture.copy(kind = "image/x-xdrive-node-ref"),
            fixture.copy(wrappedKey = Base64.getEncoder().encodeToString(ByteArray(60))),
            fixture.copy(ciphertext = Base64.getEncoder().encodeToString(ByteArray(32))),
        )) {
            assertThrows(Exception::class.java) {
                XDriveClipboardTargetCrypto.decrypt(scope, wire.targetDeviceID, key, wire)
            }
        }
        assertThrows(Exception::class.java) {
            XDriveClipboardTargetCrypto.decrypt(scope + ":other", fixture.targetDeviceID, key, fixture)
        }
        assertThrows(Exception::class.java) {
            XDriveClipboardTargetCrypto.decrypt(scope, fixture.targetDeviceID,
                XDriveClipboardTargetCrypto.newDeviceKey().pkcs8Private, fixture)
        }
    }

    @Test fun generatedDeviceKeysAreWellFormedAndDistinct() {
        val first = XDriveClipboardTargetCrypto.newDeviceKey()
        val second = XDriveClipboardTargetCrypto.newDeviceKey()
        assertEquals(32, Base64.getDecoder().decode(first.publicKeyBase64).size)
        assertEquals(48, first.pkcs8Private.size)
        assertFalse(first.publicKeyBase64 == second.publicKeyBase64)
    }
}
